<script lang="ts">import {page}from '$app/state';import {getConnection,pipelineErrorMessage,testConnection,updateConnection,type ConnectionDefinition,type NexetlError}from '$lib/api/pipelines';import PageHeader from '$lib/components/ui/PageHeader.svelte';import Alert from '$lib/components/ui/Alert.svelte';import LoadingState from '$lib/components/ui/LoadingState.svelte';import ConnectionForm from '$lib/components/connections/ConnectionForm.svelte';let item=$state<ConnectionDefinition|null>(null),loading=$state(true),pending=$state(false),error=$state(''),notice=$state('');$effect(()=>{if(page.params.connectionId)void load(page.params.connectionId)});async function load(id:string){try{item=await getConnection(id)}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{loading=false}}async function save(value:Parameters<typeof updateConnection>[1]){if(!item)return;pending=true;try{item=await updateConnection(item.id,value);notice='Connection saved.'}catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{pending=false}}async function test(){if(!item)return;pending=true;try{const result=await testConnection(item.id);notice=`Connection succeeded in ${result.latencyMs} ms · ${result.database}` }catch(e){error=pipelineErrorMessage(e as NexetlError)}finally{pending=false}}</script>
<svelte:head><title>{item?.name??'Connection'} | NEXETL</title></svelte:head>{#if loading}<LoadingState/>{:else if item}<PageHeader title={item.name} description="Connection configuration and connectivity."/>{#if error}<Alert variant="error">{error}</Alert>{/if}{#if notice}<Alert variant="success">{notice}</Alert>{/if}{#key item.updatedAt}<ConnectionForm initial={item} {pending} onsubmit={save} ontest={test}/>{/key}{/if}
